import re


def parse_version(v_str):
    if not isinstance(v_str, str):
        raise ValueError("Invalid version")
    m = re.match(r'^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$', v_str)
    if not m:
        raise ValueError(f"Invalid version: {v_str}")

    major_s, minor_s, patch_s = m.group(1), m.group(2), m.group(3)
    if len(major_s) > 1 and major_s[0] == '0': raise ValueError("Leading zero in MAJOR")
    if len(minor_s) > 1 and minor_s[0] == '0': raise ValueError("Leading zero in MINOR")
    if len(patch_s) > 1 and patch_s[0] == '0': raise ValueError("Leading zero in PATCH")

    major, minor, patch = int(major_s), int(minor_s), int(patch_s)
    pre_str = m.group(4)
    if pre_str is not None:
        pre_ids = pre_str.split('.')
        for pid in pre_ids:
            if not pid:
                raise ValueError("Invalid prerelease identifier")
            if all(c in '0123456789' for c in pid) and len(pid) > 1 and pid[0] == '0':
                raise ValueError("Invalid numeric prerelease identifier")
        pre = tuple(pre_ids)
    else:
        pre = None
    return (major, minor, patch, pre)


def compare_versions(v1, v2):
    for i in range(3):
        if v1[i] < v2[i]: return -1
        if v1[i] > v2[i]: return 1

    p1, p2 = v1[3], v2[3]
    if p1 is None and p2 is None: return 0
    if p1 is None: return 1
    if p2 is None: return -1

    for a, b in zip(p1, p2):
        a_num = all(c in '0123456789' for c in a)
        b_num = all(c in '0123456789' for c in b)
        if a_num and b_num:
            ai, bi = int(a), int(b)
            if ai < bi: return -1
            if ai > bi: return 1
        elif a_num:
            return -1
        elif b_num:
            return 1
        else:
            if a < b: return -1
            if a > b: return 1
    if len(p1) < len(p2): return -1
    if len(p1) > len(p2): return 1
    return 0


def parse_comparator(token):
    token = token.strip()
    if not token:
        raise ValueError("Empty comparator")
    m = re.match(r'^(>=|<=|>|<|=|\^|~)?(.+)$', token)
    if not m:
        raise ValueError(f"Invalid comparator: {token}")
    op = m.group(1)
    ver_str = m.group(2)
    if op is None:
        op = '='
    ver = parse_version(ver_str)
    return (op, ver)


def parse_range(rng_str):
    rng_str = rng_str.strip()
    if not rng_str:
        raise ValueError("Empty range")
    sets = []
    for set_str in rng_str.split('||'):
