import heapq


class CycleError(Exception):
    def __init__(self, cycle):
        super().__init__("dependency cycle: " + " -> ".join(cycle))
        self.cycle = cycle


def build_order(deps):
    """`deps` maps each target (str) to an iterable of targets it depends on (duplicates allowed). Targets that only
    appear as dependencies are leaves. Return a list of ALL targets in which every target comes after all of its
    dependencies. Whenever several targets are ready, the lexicographically smallest is placed first, so the
    order is unique.

    If the graph has a cycle (including a target depending on itself), raise CycleError(cycle) where `cycle`
    lists the targets on the cycle: it starts with the lexicographically smallest target ON the cycle, each element
    depends on the next one, and it ends by repeating the first element (e.g. ["a", "b", "a"], or ["x", "x"]).
    Targets that merely lead into a cycle are not part of it. Inputs with cycles contain exactly one cycle.
    `deps` must not be modified.
    """
    # Collect all unique targets
    targets = set(deps.keys())
    for d_list in deps.values():
        targets.update(d_list)

    # Build adjacency list and in-degree counts
    # adj[dep] contains list of targets that depend on dep
    adj = {t: [] for t in targets}
    in_degree = {t: 0 for t in targets}

    for t in targets:
        for dep in deps.get(t, []):
            adj[dep].append(t)
            in_degree[t] += 1

    # Min-heap for lexicographical tie-breaking
    heap = [t for t in targets if in_degree[t] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    # If not all targets are processed, there is a cycle
    if len(result) < len(targets):
        unprocessed = set(t for t in targets if t not in result)

        # Find the actual cycle nodes by removing nodes that are not part of the cycle.
        # We compute in-degrees within the unprocessed subgraph and iteratively remove nodes with in-degree 0.
        # The remaining nodes form the cycle.
        unprocessed_in_degree = {t: 0 for t in unprocessed}
        unprocessed_adj = {t: [] for t in unprocessed}

        for t in unprocessed:
            for dep in deps.get(t, []):
                if dep in unprocessed:
                    unprocessed_in_degree[t] += 1
                    unprocessed_adj[dep].append(t)

        queue = [t for t in unprocessed if unprocessed_in_degree[t] == 0]
        while queue:
            u = queue.pop()
            unprocessed.discard(u)
            for v in unprocessed_adj[u]:
                unprocessed_in_degree[v] -= 1
                if unprocessed_in_degree[v] == 0:
                    queue.append(v)

        # Now unprocessed contains exactly the cycle nodes
        start = min(unprocessed)
        cycle = [start]
        curr = start
        while True:
            next_node = None
            for dep in deps.get(curr, []):
                if dep in unprocessed:
                    next_node = dep
                    break
            if next_node is None:
                break
            cycle.append(next_node)
            curr = next_node
            if curr == start:
                break
        raise CycleError(cycle)

    return result
