    appear as dependencies are leaves. Return a list of ALL targets in which every target comes after all of its
    dependencies. Whenever several targets are ready, the lexicographically smallest is placed first, so the
    order is unique.

    If the graph has a cycle (including a target depending on itself), raise CycleError(cycle) where `cycle`
    lists the targets on the cycle: it starts with the lexicographically smallest target ON the cycle, each element
    depends on the next one, and it ends by repeating the first element (e.g. ["a", "b", "a"], or ["x", "x"]).
    Targets that merely lead into a cycle are not part of it. Inputs with cycles contain exactly one cycle.
    `deps` must not be modified.
    """
    all_nodes = set(deps.keys())
    for targets in deps.values():
        all_nodes.update(targets)

    adj = {node: [] for node in all_nodes}
    rev_adj = {node: [] for node in all_nodes}
    in_degree = {node: 0 for node in all_nodes}

    for target, dependencies in deps.items():
        seen = set()
        for dep in dependencies:
            if dep not in seen:
                seen.add(dep)
                adj[target].append(dep)
                rev_adj[dep].append(target)
                in_degree[target] += 1

    heap = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(heap)
    result = []

    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in rev_adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    if len(result) < len(all_nodes):
        cycle_candidates = set(node for node in all_nodes if node not in result)

        in_cycle_candidates = {node: 0 for node in cycle_candidates}
        for u in cycle_candidates:
            for v in adj[u]:
                if v in cycle_candidates:
                    in_cycle_candidates[v] += 1

        queue = [node for node in cycle_candidates if in_cycle_candidates[node] == 0]
        while queue:
            u = queue.pop(0)
            cycle_candidates.discard(u)
            for v in adj[u]:
                if v in cycle_candidates:
                    in_cycle_candidates[v] -= 1
                    if in_cycle_candidates[v] == 0:
                        queue.append(v)

        start = min(cycle_candidates)
        cycle = [start]
        curr = start
        while True:
